/* Avartan service worker. Generated by build.py: do not edit the copy in a release.
   Cache name changes automatically whenever any app file changes (content hash). */
const CACHE = 'avartan-139f2f1ce0';
const SHELL = [
  "./",
  "./app.js",
  "./apple-touch-icon.png",
  "./icon-192.png",
  "./icon-512-maskable.png",
  "./icon-512.png",
  "./index.html",
  "./manifest.json",
  "./minisearch.min.js",
  "./search-core.js",
  "./search.js",
  "./style.css"
];   // cache-first: app code, styles, icons
const DATA  = [
  "./answers-data.json",
  "./cards-data.json",
  "./flags-data.json",
  "./fullchap-data.json",
  "./glossary-data.json",
  "./players-data.json",
  "./quiz-data.json",
  "./search-index.json",
  "./taal-data.json"
];    // stale-while-revalidate: content files
const ALL = SHELL.concat(DATA);

self.addEventListener('install', (e) => {
  e.waitUntil(
    caches.open(CACHE)
      // cache:'reload' skips the browser's own HTTP cache so we never precache stale copies
      .then((cache) => Promise.all(ALL.map((u) =>
        fetch(new Request(u, { cache: 'reload' })).then((r) => {
          if (!r.ok) throw new Error(u + ' ' + r.status);
          return cache.put(u, r);
        }))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

const DATA_NAMES = DATA.map((d) => d.replace(/^\.\//, ''));
function isData(url) {
  const name = new URL(url).pathname.split('/').pop();
  return DATA_NAMES.indexOf(name) !== -1;
}

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  if (isData(req.url)) {
    // stale-while-revalidate: answer instantly from cache, refresh quietly for next time
    e.respondWith(
      caches.open(CACHE).then((cache) =>
        cache.match(req, { ignoreSearch: true }).then((cached) => {
          const refresh = fetch(req, { cache: 'no-cache' }).then((res) => {
            if (res && res.ok) cache.put(req, res.clone());
            return res;
          }).catch(() => null);
          if (cached) { e.waitUntil(refresh); return cached; }
          return refresh.then((res) => res || Response.error());
        })
      )
    );
    return;
  }

  // app shell: cache-first, falling back to network, then to the cached home page
  e.respondWith(
    caches.match(req, { ignoreSearch: true }).then((cached) => {
      if (cached) return cached;
      return fetch(req).then((res) => {
        if (res.ok && res.type === 'basic') {
          const copy = res.clone();
          caches.open(CACHE).then((c) => c.put(req, copy));
        }
        return res;
      }).catch(() => (req.mode === 'navigate' ? caches.match('./index.html') : Response.error()));
    })
  );
});
